#[test]
fn test_holt_winters_forecast_basic() {
    let config = HoltWintersConfig::default();
    let mut hw = HoltWinters::new(config).unwrap();
    
    // Generate synthetic seasonal data
    let data: Vec<f64> = (0..24)
        .map(|i| 10.0 + (i as f64 * 0.5) + (i as f64 / 3.0).sin() * 2.0)
        .collect();
    
    hw.fit(&data).unwrap();
    let forecast = hw.forecast(5).unwrap();
    
    assert_eq!(forecast.len(), 5);
    for f in &forecast {
        assert!(f.value.is_finite());
        assert!(f.lower_bound <= f.value);
        assert!(f.upper_bound >= f.value);
    }
}

