#[test]
fn test_drift_detector_stable_sequence() {
    let config = DriftDetectorConfig {
        threshold: 0.1,
        window_size: 10,
    };
    let mut detector = DriftDetector::new(config);
    
    // Stable data sequence
    for i in 0..20 {
        let value = 5.0 + (i as f64 * 0.01);
        detector.update(value);
    }
    
    assert_eq!(detector.state(), DriftState::Stable);
}

#[test]
fn test_drift_detector_detects_drift() {
    let config = DriftDetectorConfig {
        threshold: 0.5,
        window_size: 10,
    };
    let mut detector = DriftDetector::new(config);
    
    // Stable baseline
    for _ in 0..10 {
        detector.update(10.0);
    }
    
    // Sudden shift
    for _ in 0..10 {
        detector.update(20.0);
    }
    
    assert_eq!(detector.state(), DriftState::DriftDetected);
}

#[test]
fn test_drift_detector_recovers_to_stable() {
    let config = DriftDetectorConfig {
        threshold: 0.5,
        window_size: 10,
    };
    let mut detector = DriftDetector::new(config);
    
    // Stable baseline
    for _ in 0..10 {
        detector.update(10.0);
    }
    
    // Drift
    for _ in 0..10 {
        detector.update(20.0);
    }
    assert_eq!(detector.state(), DriftState::DriftDetected);
    
    // Recovery
    for _ in 0..10 {
        detector.update(10.0);
    }
    assert_eq!(detector.state(), DriftState::Stable);
}

#[test]
fn test_drift_detector_gradual_drift() {
    let config = DriftDetectorConfig {
        threshold: 0.3,
        window_size: 20,
    };
    let mut detector = DriftDetector::new(config);
    
    // Gradual increase
    for i in 0..50 {
        detector.update(i as f64 * 0.5);
    }
    
    assert_eq!(detector.state(), DriftState::DriftDetected);
}

