#[test]
fn test_concurrent_forecast_and_drift() {
    // Test both modules working together
    let hw_config = HoltWintersConfig::default();
    let mut hw = HoltWinters::new(hw_config).unwrap();
    
    let data: Vec<f64> = (0..50).map(|i| 50.0 + (i as f64 * 0.5)).collect();
    hw.fit(&data).unwrap();
    
    let mut detector = DriftDetector::new(DriftDetectorConfig {
        threshold: 0.1,
        window_size: 10,
    });
    
    // Feed forecast values to drift detector
    let forecast = hw.forecast(10).unwrap();
    for f in &forecast {
        detector.update(f.value);
    }
    
    // Should remain stable with consistent forecast
    assert_eq!(detector.state(), DriftState::Stable);
}

