#[test]
fn test_forecast_confidence_intervals() {
    let config = HoltWintersConfig::default();
    let mut hw = HoltWinters::new(config).unwrap();
    
    // Noisy data should produce wider confidence intervals
    let noisy_data: Vec<f64> = (0..50)
        .map(|i| 100.0 + (i as f64 * 0.1) + (i as f64 % 5.0) * 3.0)
        .collect();
    
    hw.fit(&noisy_data).unwrap();
    let forecast = hw.forecast(5).unwrap();
    
    // Confidence interval width should be positive
    for f in &forecast {
        let width = f.upper_bound - f.lower_bound;
        assert!(width > 0.0);
    }
}

#[test]
fn test_forecast_accuracy_on_known_function() {
    let config = HoltWintersConfig {
        alpha: 0.5,
        beta: 0.3,
        gamma: 0.4,
        seasonal_periods: 4,
        seasonal_mode: SeasonalMode::Additive,
    };
    let mut hw = HoltWinters::new(config).unwrap();
    
    // Known function: y = 2x + sin(x)
    let data: Vec<f64> = (0..40)
        .map(|i| 2.0 * i as f64 + (i as f64).sin())
        .collect();
    
    hw.fit(&data).unwrap();
    let forecast = hw.forecast(1).unwrap();
    
    // Actual next value: 2*40 + sin(40) ≈ 80.75
    let actual = 2.0 * 40.0 + (40.0_f64).sin();
    let error = (forecast[0].value - actual).abs();
    
    // Allow reasonable error margin
    assert!(error < 5.0, "Forecast error too large: {}", error);
}

