#[cfg(test)]
mod integration_tests {
    use super::*;
    
    #[test]
    fn test_full_system_integration() {
        // Complete system integration test
        let hw_config = HoltWintersConfig {
            alpha: 0.3,
            beta: 0.2,
            gamma: 0.1,
            seasonal_periods: 12,
            seasonal_mode: SeasonalMode::Multiplicative,
        };
        
        let mut hw = HoltWinters::new(hw_config).unwrap();
        
        // Monthly data with yearly seasonality
        let data: Vec<f64> = (0..48)
            .map(|i| {
                let month = i % 12;
                let base = 100.0 + i as f64 * 0.5;
                let seasonal = match month {
                    0 => 20.0,
                    1 => 15.0,
                    2 => 10.0,
                    3 => 5.0,
                    4 => 0.0,
                    5 => -5.0,
                    6 => -10.0,
                    7 => -5.0,
                    8 => 0.0,
                    9 => 5.0,
                    10 => 10.0,
                    _ => 15.0,
                };
                base + seasonal
            })
            .collect();
        
        hw.fit(&data).unwrap();
        let forecast = hw.forecast(12).unwrap();
        
        // Validate forecast follows seasonal pattern
        assert_eq!(forecast.len(), 12);
        assert!(forecast[0].value > forecast[6].value); // January > July
    }
}